$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;Set-Location $root
function Headers($token){@{Authorization="Bearer $token"}}
$admin=(Invoke-RestMethod -SkipCertificateCheck -Method Post -Uri 'https://localhost:3001/api/auth/login' -ContentType 'application/json' -Body (@{identity='admin';password='ChangeMe-Admin-2026!'}|ConvertTo-Json)).access_token
$roles=Invoke-RestMethod -SkipCertificateCheck -Uri 'https://localhost:3001/api/roles' -Headers (Headers $admin);$users=Invoke-RestMethod -SkipCertificateCheck -Uri 'https://localhost:3001/api/users' -Headers (Headers $admin)
$definitions=@(@{username='analyst';cedula='1111111111';nombres='Ana';apellidos='Analista';email='analyst@example.local';password='Analyst-Pass-2026!';roles=@('ANALYST','USER')},@{username='user';cedula='2222222222';nombres='Una';apellidos='Usuario';email='user@example.local';password='User-Secure-2026!';roles=@('USER')})
foreach($definition in $definitions){$current=$users|Where-Object username -eq $definition.username;if(!$current){$body=@{cedula=$definition.cedula;nombres=$definition.nombres;apellidos=$definition.apellidos;fechaNacimiento='1995-01-01';username=$definition.username;email=$definition.email;password=$definition.password}|ConvertTo-Json;$current=Invoke-RestMethod -SkipCertificateCheck -Method Post -Uri 'https://localhost:3001/api/users' -Headers (Headers $admin) -ContentType 'application/json' -Body $body}foreach($roleName in $definition.roles){$role=$roles|Where-Object rol -eq $roleName;try{Invoke-RestMethod -SkipCertificateCheck -Method Post -Uri 'https://localhost:3001/api/user-roles' -Headers (Headers $admin) -ContentType 'application/json' -Body (@{userId=$current.id;roleId=$role.id}|ConvertTo-Json)|Out-Null}catch{if([int]$_.Exception.Response.StatusCode -ne 409){throw}}}}
Write-Output 'Datos demo listos: admin, analyst (ANALYST+USER) y user (USER).'
